tree.p.k7/chains/drums.k7x:
// The drums lane: into the mix, and into `glow`'s audio port — see glow.k7x.
start(true)
steps([
  id("32ed90b2-df56-4d98-9d9d-d8087c5e2e86").track("drums"),
  to([chain("MIX").level(1), chain("glow").port("audio").level(1)]),
])

tree.p.k7/chains/glow.k7x:
// The shader the main lane runs through. Its `audio` port is a SIDE input: the drums lane feeds it
// as well as the mix, and `uAudio` is that lane's live level, so the picture moves with the kit.
ports(["audio"])
steps([
  id("078a9886-bfac-42a4-9a04-1bf1dfdb7378").extends("@workspace/shaders/glow"),
  to([chain("RENDER")]),
])

tree.p.k7/chains/main.k7x:
// The picture lane `main`: a `video_track` item heads its chain, and its placements live in
// video_tracks/main. Its run goes through the `glow` shader on its way to RENDER.
//
// `iris` is a SUBCHAIN that nothing links and that links nowhere: a fade's STRETCH. The second shot
// on main names it (`fade_in: { over: 1, chain: iris }`) and runs through it on its way in.
// See packages/song-video/docs/transitions.md and packages/song/docs/chainFiles.md.
start(true)
steps([id("e236ac58-39aa-4710-8afd-dd3e145f5514").video_track("main"), to([chain("glow")])])
subchains([
  id("iris").steps([id("3663c123-f41a-40d0-9a42-27b538d4faf8").extends("@workspace/shaders/iris")]),
])

tree.p.k7/chains/picture.k7x:
// The PICTURE's run: RENDER is where the lanes composite and VIDEO_OUT is the frame that leaves.
// Neither carries a param — a frame has no level. See packages/song/docs/videoOutputs.md.
start("RENDER")
steps([to([chain("VIDEO_OUT")])])

